CREATE   VIEW [CE].[vwPhonecall]
AS 
SELECT 
	pc.[ActivityId],
	pc.[ActivityTypeCode],
	pc.[ActualStart],
	pc.[ActualEnd],
	pc.[Category],
	pc.[CreatedBy],
	pc.[CreatedByName],
	pc.[Created_On],
	pc.[ModifiedBy],
	pc.[ModifiedByName],
	pc.[Modified_On],
	pc.[Description],
	pc.[DirectionCode],
	pc.[DirectionCode_Description],
	pc.[OwnerId],
	pc.[OwnerIdName],
	pc.[RegardingObjectId],
	--[RegardingObjectIdName],
	pc.[StateCode],
	pc.[StateCode_Description],
	pc.[StatusCode],
	pc.[StatusCode_Description],
	pc.[Subject],
	pc.[Subcategory],
	pc.[apuk_subjectareaid],
	pc.[apuk_subjectareaid_description],
	pc.[prioritycode],
	pc.[prioritycode_description],
	pc.[onholdtime],
	pc.[apitil_precedingactivitycompleted],
	pc.[apitil_precedingactivitytask],
	pc.[apitil_precedingactivityphonecall],
	pc.[apitil_nextactivitytask],
	pc.[apitil_nextactivityphonecall],
	pc.[apitil_movetostage],
	pc.[actualdurationminutes],
	pc.[msdyn_ci_keywords],
	cnt.[EMailAddress1],
	cnt.[Rics_MemberGrade]
FROM [synapse_ce].[vwPhonecall] pc
	LEFT JOIN synapse_ce.tblContact_BI cnt
		ON pc.[RegardingObjectId] = cnt.[ContactId]
